safe-state.pseudocode:
def is_safe(avail, alloc, need):  # 은행가 안전성 검사
    work = avail[:]  # 현재 사용 가능 자원
    n, m = len(alloc), len(avail)
    finish = [False] * n
    order = []
    while len(order) < n:
        found = False
        for i in range(n):
            if finish[i]:
                continue
            if all(need[i][j] <= work[j] for j in range(m)):
                for j in range(m):
                    work[j] += alloc[i][j]  # 완료 후 반납
                finish[i] = True
                order.append(i)
                found = True
        if not found:
            return False, order  # 불안전 상태
    return True, order  # 안전 순서열

sat-solver.pseudocode:
def val(lit, a):  # 리터럴 값: True/False/None(미할당)
    v = a.get(abs(lit))
    return None if v is None else v == (lit > 0)

def dpll(cnf, a):  # cnf: 절 리스트, 리터럴은 ±변수번호
    changed = True
    while changed:  # 단위 전파(BCP)
        changed = False
        for c in cnf:
            vals = [val(l, a) for l in c]
            if True in vals:
                continue  # 이미 충족된 절
            free = [l for l, v in zip(c, vals) if v is None]
            if not free:
                return None  # 충돌: 모든 리터럴 거짓
            if len(free) == 1:  # 단위 절 → 강제 할당
                a[abs(free[0])] = free[0] > 0
                changed = True
    free = {abs(l) for c in cnf for l in c} - set(a)
    if not free:
        return a  # SAT: 충족 할당(= 반례)
    v = min(free)  # 결정 변수 선택
    for b in (True, False):
        r = dpll(cnf, {**a, v: b})
        if r is not None:
            return r
    return None  # UNSAT (CDCL은 학습 절 + 백점프)
